+        { value: "SMS", label: "SMS" },
+        { value: "Push Notifications", label: "Push Notifications" }
+      ];
+
+      return `
+        <div class="form-field">
+          <div class="question-title">How do you prefer to receive notifications?</div>
+          <div class="radio-group" role="radiogroup" aria-labelledby="notification-question">
+            ${options
+              .map((option, index) =>
+                RadioOption({
+                  name: "notificationPreference",
+                  value: option.value,
+                  label: option.label,
+                  checked: index === 0
+                })
+              )
+              .join("")}
+          </div>
+        </div>
+      `;
+    }
+
+    function SubmitButton() {
+      return '<button type="submit">Submit</button>';
+    }
+
+    function FormSection() {
+      return `
+        <form>
+          ${NotificationQuestion()}
+          ${SubmitButton()}
+        </form>
+      `;
+    }
+
+    function App() {
+      return `
+        <main class="app-shell">
+          <p class="eyebrow">Preferences</p>
+          <h1>Notification Settings</h1>
+          <p class="intro">Choose one option below to tell us how you would like to receive updates.</p>
+          ${FormSection()}
+        </main>
+      `;
+    }
+
+    document.getElementById("app").innerHTML = App();
+  </script>
+</body>
+</html>
*** End Patch
